1	'use client';
2	// 用到 React hook 或 Base UI 的模組標成 client 元件，Next App Router 的伺服器元件才能匯入套件入口（PR-ADOPT-01）。
3	import { createContext, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode, type RefObject } from 'react';
4	import { modeAttribute, modeStorageKey, suiteAttribute, themeAttribute } from './theme-init.js';
5	import type { ColorMode, Density, Shape, StyleSuite } from './theme-types.js';
6	import { deriveAccent, type AccentInput } from '@luca-style/tokens/accent';
7	import tokenData from '@luca-style/tokens/data' with { type: 'json' };
8	export type { AccentInput } from '@luca-style/tokens/accent';
9	export type { ColorMode, Density, Shape, StyleSuite } from './theme-types.js';
10	export type ThemeTarget = 'self' | 'document';
11	// 資訊密度與元件外形的屬性名；只由 ThemeProvider 寫入，首屏腳本不處理（架構 §3.3）。
12	const densityAttribute = 'data-density';
13	const shapeAttribute = 'data-shape';
14	export type ThemeProviderProps = {
15	  suite?:StyleSuite;
16	  // 只有日間主色必填；其餘沒給時由 deriveAccent 推算（架構 §3.3）。
17	  accent?:AccentInput;
18	  // 資訊密度與元件外形可單獨覆寫；沒給時沿用風格套系的預設等級（ADR 0005）。
19	  density?:Density;
20	  shape?:Shape;
21	  // false 時完全不讀寫瀏覽器儲存，偏好只存在本次頁面。
22	  persist?:boolean;
23	  // document 時主題屬性與強調色變數套在 <html>，不另包外層元素。
24	  target?:ThemeTarget;
25	  children:ReactNode;
26	};
27	const ThemeContext = createContext<{mode:ColorMode; resolvedMode:'light'|'dark'; setMode:(mode:ColorMode)=>void} | null>(null);
28	// 彈出層（例如 Select 選單）的 portal 容器，不對外公開：target="self" 時是外層 div，主題屬性與行內強調色變數靠繼承套到彈出層；
29	// target="document" 或沒有 ThemeProvider 時為 null，交給 Base UI 預設的 document.body（<html> 已帶主題屬性）。
30	const PortalContainerContext = createContext<RefObject<HTMLDivElement | null> | null>(null);
31	export function usePortalContainer() { return useContext(PortalContainerContext); }
32	function storedMode():ColorMode {
33	  try { const value = localStorage.getItem(modeStorageKey); return value === 'dark' || value === 'light' ? value : 'system'; } catch { return 'system'; }
34	}
35	export function ThemeProvider({suite='vibrant', accent, density, shape, persist=true, target='self', children}: ThemeProviderProps) {
36	  const [mode, updateMode] = useState<ColorMode>(() => persist ? storedMode() : 'system');
37	  const [dark, setDark] = useState(() => typeof matchMedia !== 'undefined' && matchMedia('(prefers-color-scheme: dark)').matches);
38	  useEffect(() => {
39	    const media = matchMedia('(prefers-color-scheme: dark)');
40	    const sync = () => setDark(media.matches);
41	    sync(); media.addEventListener('change', sync);
42	    return () => media.removeEventListener('change', sync);
43	  }, []);
44	  const setMode = (value:ColorMode) => {
45	    updateMode(value);
46	    if (!persist) return;
47	    try { if(value === 'system') localStorage.removeItem(modeStorageKey); else localStorage.setItem(modeStorageKey,value); } catch { /* 儲存不可用時維持目前頁面的選擇。 */ }
48	  };
49	  const resolvedMode = mode === 'system' ? dark ? 'dark' : 'light' : mode;
50	  // 主題屬性與強調色變數只算一份，依 target 套到外層 div 或 <html>。
51	  // density、shape 沒給就不寫屬性，tokens CSS 的套系區塊即為預設值，畫面與 0.1.0 相同（PR-STYLE-29）。
52	  const attributes:Record<string,string> = {[themeAttribute]:'', [suiteAttribute]:suite, [modeAttribute]:resolvedMode,
53	    ...(density && {[densityAttribute]:density}), ...(shape && {[shapeAttribute]:shape})};
54	  // 中性色取自設計變數輸出，與建置時推算套系預設色用的是同一組值。
55	  // 推算要走數次明度搜尋，只在輸入、套系或明暗改變時重算；accent 物件常是每次 render 新建，故以內容當鍵。
56	  const accentKey = accent ? JSON.stringify(accent) : '';
57	  const variables = useMemo<Record<string,string>>(() => accentKey
58	    ? Object.fromEntries(Object.entries(deriveAccent(JSON.parse(accentKey), resolvedMode, tokenData[suite][resolvedMode])).map(([name,value]) => [`--${name}`, value]))
59	    : {}, [accentKey, suite, resolvedMode]);
60	  const toDocument = target === 'document';
61	  const container = useRef<HTMLDivElement>(null);
62	  const attributeKey = JSON.stringify(attributes), variableKey = JSON.stringify(variables);
63	  useLayoutEffect(() => {
64	    if (!toDocument) return;
65	    const root = document.documentElement;
66	    const applied:Record<string,string> = JSON.parse(attributeKey);
67	    const styles:Record<string,string> = JSON.parse(variableKey);
68	    for (const [name,value] of Object.entries(applied)) root.setAttribute(name,value);
69	    for (const [name,value] of Object.entries(styles)) root.style.setProperty(name,value);
70	    // 卸載或改值時清掉本次套上的屬性與變數，避免殘留在 <html>。
71	    return () => {
72	      for (const name of Object.keys(applied)) root.removeAttribute(name);
73	      for (const name of Object.keys(styles)) root.style.removeProperty(name);
74	    };
75	  }, [toDocument, attributeKey, variableKey]);
76	  const value = {mode,resolvedMode,setMode};
77	  if (toDocument) return <ThemeContext.Provider value={value}><PortalContainerContext.Provider value={null}>{children}</PortalContainerContext.Provider></ThemeContext.Provider>;
78	  return <ThemeContext.Provider value={value}><PortalContainerContext.Provider value={container}><div ref={container} {...attributes} style={accent ? variables as CSSProperties : undefined}>{children}</div></PortalContainerContext.Provider></ThemeContext.Provider>;
79	}
80	export function useTheme() { const theme = useContext(ThemeContext); if(!theme) throw new Error('useTheme requires ThemeProvider'); return theme; }
